/*
	rects in the wind #genuary18 #genuary #genuary2518
	What does wind look like?
	https://openprocessing.org/sketch/2503156
	#generativeart #creativecoding #p5js
*/
let cnt = 0;
let BG = "#202020";
let PAD = 4;

function setup() {
  createCanvas(innerWidth, innerWidth*0.3);
  frameRate(30);
  noFill();
  stroke("rgba(0,0,0,0.1)");

  loop();
  cnt = 0;
}

function draw() {
  // for (let j = 0; j < 1; j++) {
	background(BG)

	noStroke()
  fill("tan");
	rectMode(CORNER);
	// rect(PAD, PAD, width-PAD-PAD, height-PAD-PAD)
	rect(0, 0, width, height)
	noFill();
	stroke("rgba(0,0,0,0.1)");
	rectMode(CENTER);

    let SZE = 100;
    for (let x = SZE * 0.75; x < width * 0.925; x += SZE * 0.00725) {
      push();
      const y = height / 2;
      const dF = noise(x / 23, y / 43, frameCount / 143) - 0.5;
      translate(x, y + SZE * 2 * dF * map(x, 0, width, 0.5, 4));
      const angle = noise(x / 23, y / 41, frameCount / 143) * TWO_PI;
      const szeF = noise(x / 93, y / 66, frameCount / 143);
      rotate(angle);
      rect(0, 0, SZE * szeF); cnt++;

      pop();
    }



    // frame
    if (true) {
      push();
      const sw = 10;
      strokeWeight(sw);
      stroke(BG);
      fill(BG);
      rectMode(CORNER);
      for (let i = 1, num=4; i < num; i++) {
        const x = width/num * i;
        if (true || cnt < 1000000) {
          line(x, 0, x, height); cnt++;
        }
      }
      pop();
    }
  // }

	drawMsg("rects in the wind #2 (epi) #genuary2518")
}

function drawMsg(msg) {
	push();

	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 1, 1)

	fill("black")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)

	pop();
}
